const test = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');
const net = require('node:net');
const { once } = require('node:events');
const { spawn } = require('node:child_process');
const path = require('node:path');

test('GET /api/hello returns the exact hello body', async () => {
  const server = spawn(process.execPath, [path.join(__dirname, '..', 'server.js')], {
    stdio: 'ignore',
  });
  const exited = once(server, 'close').then(() => ({ exited: true }));
  const ready = waitForListening();

  try {
    const target = await Promise.race([ready, exited]);
    if (target.exited) {
      assertionError(`server exited before responding (exit code ${server.exitCode})`);
    }
    const { address, port } = target;
    const rawBody = await new Promise((resolve, reject) => {
      const request = http.request({
        hostname: address,
        port,
        path: '/api/hello',
        method: 'GET',
      }, (response) => {
        response.setEncoding('utf8');

        let body = '';
        response.on('data', (chunk) => {
          body += chunk;
        });
        response.on('end', () => {
          if (response.statusCode !== 200) {
            reject(assertionError(`Expected status 200, received ${response.statusCode}`));
            return;
          }
          resolve(body);
        });
      });

      request.on('error', reject);
      request.end();
    });

    assert.equal(rawBody, '{"message":"hello"}');
  } finally {
    server.kill();
    await exited;
  }
});

function waitForListening(server) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let attempts = 0;

    const connect = () => {
      attempts += 1;
      const socket = net.connect({
        host: '127.0.0.1',
        port: 3000,
      });

      socket.once('connect', () => {
        if (settled) return;
        settled = true;
        socket.destroy();
        resolve({ address: '127.0.0.1', port: 3000, exited: false });
      });
      socket.once('error', () => {
        socket.destroy();
        if (settled) return;
        if (attempts >= 50) {
          settled = true;
          reject(assertionError('server did not become ready'));
          return;
        }
        setTimeout(connect, 20);
      });
    };

    connect();
  });
}

function assertionError(message) {
  assert.fail(message);
}

